from typing import Any

from contracts import request_from_payload
from event_log import EventLog
from hook_dispatcher import HookDispatcher
from hook_registry import HookRegistry
from metrics import Metrics
from tenant_policy import can_execute
from service_layer import WorkflowService
from state_store import StateStore


class WorkflowFacade:
    def __init__(self) -> None:
        self.state = StateStore()
        self.registry = HookRegistry()
        self.dispatcher = HookDispatcher(self.registry)
        self.events = EventLog()
        self.metrics = Metrics()
        self.service = WorkflowService(
            state=self.state,
            dispatcher=self.dispatcher,
            events=self.events,
            metrics=self.metrics,
        )

    def seed(self, records: list[dict[str, Any]]) -> None:
        self.state.seed(records)
        self.events.clear()
        self.metrics.clear()
        self.dispatcher.clear()

    def register_hook(self, event_type: str, handler) -> None:
        self.registry.register(event_type, handler)

    def handle(self, payload: dict[str, Any]) -> dict[str, Any]:
        try:
            req = request_from_payload(payload)
        except Exception as exc:
            return {"ok": False, "reason": f"invalid_payload:{exc}", "data": {}}

        role = str(payload.get("role", "admin")).strip().lower()
        allowed, reason = can_execute(role, req.action)
        if not allowed:
            return {"ok": False, "reason": reason, "data": {}}

        return self.service.execute(
            {
                "request_id": req.request_id,
                "tenant_id": req.tenant_id,
                "actor_id": req.actor_id,
                "action": req.action,
                "payload": req.payload,
            }
        )

    def handle_many(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            result = self.handle(payload)
            results.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}

    def diagnostics(self) -> dict[str, Any]:
        return {
            "service": self.service.diagnostics(),
            "state": self.state.snapshot(),
            "hooks": self.registry.snapshot(),
            "dispatcher_history": self.dispatcher.history(),
        }

    def hook_history(self) -> list[dict[str, Any]]:
        return self.dispatcher.history()

    def summary(self) -> dict[str, Any]:
        diag = self.diagnostics()
        return {
            "state_count": len(diag["state"]),
            "hook_types": sorted(diag["hooks"].keys()),
            "metric_total": sum(diag["service"]["metrics"].values()),
        }

    def replay(self, payload: dict[str, Any], times: int = 1) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for _ in range(max(0, int(times))):
            out.append(self.handle(dict(payload)))
        return out

    def replay_summary(self, payload: dict[str, Any], times: int = 1) -> dict[str, int]:
        results = self.replay(payload, times=times)
        success = 0
        failed = 0
        for result in results:
            if bool(result.get("ok", False)):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed}

    def clear_runtime(self) -> None:
        self.events.clear()
        self.metrics.clear()
        self.dispatcher.clear()

    def diagnostics_lines(self) -> list[str]:
        diag = self.diagnostics()
        lines = []
        lines.append(f"state_count={diag['service']['state_count']}")
        lines.append(f"hook_history_count={diag['service']['hook_history_count']}")
        lines.append(f"event_types={sorted(diag['hooks'].keys())}")
        lines.append(f"metrics={diag['service']['metrics']}")
        return lines

    def register_many_hooks(self, mapping: dict[str, list]) -> int:
        count = 0
        for event_type, handlers in mapping.items():
            for handler in handlers:
                self.register_hook(event_type, handler)
                count += 1
        return count

    def state_keys(self) -> list[str]:
        return sorted(self.state.snapshot().keys())

    def has_state(self, resource_id: str) -> bool:
        return self.state.has(resource_id)

    def remove_state(self, resource_id: str) -> bool:
        return self.state.remove(resource_id)

