from __future__ import annotations

from threading import Lock
from typing import Any, Callable

HookHandler = Callable[[dict[str, Any]], dict[str, Any]]


class HookRegistry:
    def __init__(self) -> None:
        self._lock = Lock()
        self._handlers: dict[str, list[HookHandler]] = {}

    def register(self, event_type: str, handler: HookHandler) -> None:
        key = event_type.strip().lower()
        if not key:
            raise ValueError("event_type required")
        if not callable(handler):
            raise ValueError("handler must be callable")
        with self._lock:
            handlers = self._handlers.setdefault(key, [])
            handlers.append(handler)

    def handlers_for(self, event_type: str) -> list[HookHandler]:
        key = event_type.strip().lower()
        if not key:
            return []
        with self._lock:
            return list(self._handlers.get(key, []))

    def count_for(self, event_type: str) -> int:
        return len(self.handlers_for(event_type))

    def event_types(self) -> list[str]:
        with self._lock:
            return sorted(self._handlers.keys())

    def clear(self) -> None:
        with self._lock:
            self._handlers.clear()

