class Metrics:
    def __init__(self) -> None:
        self._lock = Lock()
        self._values: dict[str, int] = {}

    def incr(self, key: str, amount: int = 1) -> None:
        metric = key.strip()
        if not metric:
            return
        with self._lock:
            self._values[metric] = self._values.get(metric, 0) + amount

    def get(self, key: str) -> int:
        metric = key.strip()
        if not metric:
            return 0
        with self._lock:
            return self._values.get(metric, 0)

    def snapshot(self) -> dict[str, int]:
        with self._lock:
            return dict(self._values)

    def clear(self) -> None:
        with self._lock:
            self._values.clear()

    def total(self) -> int:
        with self._lock:
            return sum(self._values.values())

    def has(self, key: str) -> bool:
        return self.get(key) > 0

    def clear_key(self, key: str) -> bool:
        metric = key.strip()
        if not metric:
            return False
        with self._lock:
            if metric in self._values:
                del self._values[metric]
                return True
        return False

    def top(self, limit: int = 5) -> list[tuple[str, int]]:
        items = sorted(self.snapshot().items(), key=lambda item: item[1], reverse=True)
        return items[: max(0, int(limit))]

