from __future__ import annotations

from typing import Any

from contracts import HookEvent, make_event, to_public_result
from event_log import EventLog
from hook_dispatcher import HookDispatcher
from metrics import Metrics
from request_parser import build_state_payload, parse_resource_id, parse_value
from state_store import StateStore


class WorkflowService:
    def __init__(
        self,
        *,
        state: StateStore,
        dispatcher: HookDispatcher,
        events: EventLog,
        metrics: Metrics,
    ) -> None:
        self._state = state
        self._dispatcher = dispatcher
        self._events = events
        self._metrics = metrics

    def execute(self, request: dict[str, Any]) -> dict[str, Any]:
        action = str(request.get("action", "")).strip().lower()
        payload = dict(request.get("payload", {}) or {})
        tenant_id = str(request.get("tenant_id", "")).strip()
        request_id = str(request.get("request_id", "")).strip()

        if action not in {"create", "update", "close"}:
            self._metrics.incr("invalid_action")
            return to_public_result(False, "invalid_action", {})

        resource_id = parse_resource_id(payload)
        if not resource_id:
            self._metrics.incr("invalid_resource_id")
            return to_public_result(False, "invalid_resource_id", {})

        current = self._state.get(resource_id)

        if action == "create":
            if current is not None:
                self._metrics.incr("already_exists")
                return to_public_result(False, "already_exists", {"resource": current})
            value = parse_value(payload, default=0)
            state_item = build_state_payload(resource_id, value, "active", tenant_id)
            self._state.save(state_item)
            self._events.add("resource_created", {"resource_id": resource_id, "tenant_id": tenant_id})
            self._metrics.incr("create_ok")
            event: HookEvent = make_event("resource_created", tenant_id, request_id, {"resource_id": resource_id})
            # Bug: hook dispatch skipped for create events.
            return to_public_result(True, "created", {"resource": state_item, "hook": None})

        if current is None:
            self._metrics.incr("not_found")
            return to_public_result(False, "not_found", {})

        if action == "update":
            value = parse_value(payload, default=current.get("value", 0))
            updated = dict(current)
            updated["value"] = value
            self._state.save(updated)
            self._events.add("resource_updated", {"resource_id": resource_id, "tenant_id": tenant_id})
            self._metrics.incr("update_ok")
            event = make_event("resource_updated", tenant_id, request_id, {"resource_id": resource_id, "value": value})
            hook_result = self._dispatcher.dispatch(event)
            return to_public_result(True, "updated", {"resource": updated, "hook": hook_result})

        # close
        updated = dict(current)
        updated["status"] = "closed"
        self._state.save(updated)
        self._events.add("resource_closed", {"resource_id": resource_id, "tenant_id": tenant_id})
        self._metrics.incr("close_ok")
        event = make_event("resource_closed", tenant_id, request_id, {"resource_id": resource_id})
        hook_result = self._dispatcher.dispatch(event)
        return to_public_result(True, "closed", {"resource": updated, "hook": hook_result})

    def diagnostics(self) -> dict[str, Any]:
        return {
            "state_count": self._state.count(),
            "events": self._events.summary(),
            "metrics": self._metrics.snapshot(),
            "hook_history_count": self._dispatcher.count(),
        }

    def execute_many(self, requests: list[dict[str, Any]]) -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for request in requests:
            result = self.execute(request)
            results.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}

    def replay(self, request: dict[str, Any], times: int = 1) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for _ in range(max(0, int(times))):
            out.append(self.execute(dict(request)))
        return out

    def replay_summary(self, request: dict[str, Any], times: int = 1) -> dict[str, int]:
        results = self.replay(request, times=times)
        success = 0
        failed = 0
        for result in results:
            if bool(result.get("ok", False)):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed}

    def state_snapshot(self) -> dict[str, dict[str, Any]]:
        return self._state.snapshot()

    def compare_before_after(self, resource_id: str, request: dict[str, Any]) -> dict[str, Any]:
        before = self._state.get(resource_id) or {}
        result = self.execute(request)
        after = self._state.get(resource_id) or {}
        return {"before": before, "after": after, "result": result}

    def metrics_total(self) -> int:
        return self._metrics.total()

