class StateStore:
    def __init__(self) -> None:
        self._lock = Lock()
        self._records: dict[str, dict[str, Any]] = {}

    def seed(self, records: list[dict[str, Any]]) -> None:
        with self._lock:
            self._records.clear()
            for record in records:
                resource_id = str(record.get("resource_id", "")).strip()
                if not resource_id:
                    raise ValueError("resource_id required")
                self._records[resource_id] = {
                    "resource_id": resource_id,
                    "status": str(record.get("status", "new")).strip().lower(),
                    "value": int(record.get("value", 0)),
                    "tenant_id": str(record.get("tenant_id", "")).strip(),
                }

    def get(self, resource_id: str) -> dict[str, Any] | None:
        key = resource_id.strip()
        if not key:
            return None
        with self._lock:
            item = self._records.get(key)
            return dict(item) if item is not None else None

    def save(self, resource: dict[str, Any]) -> None:
        resource_id = str(resource.get("resource_id", "")).strip()
        if not resource_id:
            raise ValueError("resource_id required")
        with self._lock:
            self._records[resource_id] = dict(resource)

    def list_for_tenant(self, tenant_id: str) -> list[dict[str, Any]]:
        key = tenant_id.strip()
        if not key:
            return []
        with self._lock:
            return [dict(item) for item in self._records.values() if str(item.get("tenant_id", "")) == key]

    def count(self) -> int:
        with self._lock:
            return len(self._records)

    def clear(self) -> None:
        with self._lock:
            self._records.clear()

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {key: dict(value) for key, value in self._records.items()}

    def has(self, resource_id: str) -> bool:
        return self.get(resource_id) is not None

    def remove(self, resource_id: str) -> bool:
        key = resource_id.strip()
        if not key:
            return False
        with self._lock:
            if key in self._records:
                del self._records[key]
                return True
            return False

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._records.keys())

    def values(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(item) for item in self._records.values()]

