from facade import WorkflowFacade


def _facade() -> WorkflowFacade:
    facade = WorkflowFacade()
    facade.seed(
        [
            {"resource_id": "res-1", "status": "active", "value": 10, "tenant_id": "tenant-a"},
            {"resource_id": "res-2", "status": "active", "value": 20, "tenant_id": "tenant-a"},
        ]
    )
    return facade


def test_happy_path_create_emits_hook_event():
    facade = _facade()
    called = {"count": 0}

    def on_created(payload):
        called["count"] += 1
        return {"ok": True, "reason": "sent"}

    facade.register_hook("resource_created", on_created)
    result = facade.handle(
        {
            "request_id": "r-1",
            "tenant_id": "tenant-a",
            "actor_id": "actor-1",
            "action": "create",
            "payload": {"resource_id": "res-3", "value": 5},
        }
    )
    assert result["ok"] is True
    assert called["count"] == 1


def test_edge_case_update_missing_resource_rejected():
    facade = _facade()
    result = facade.handle(
        {
            "request_id": "r-2",
            "tenant_id": "tenant-a",
            "actor_id": "actor-2",
            "action": "update",
            "payload": {"resource_id": "res-missing", "value": 7},
        }
    )
    assert result["ok"] is False
    assert result["reason"] == "not_found"


def test_boundary_condition_close_existing_resource_succeeds():
    facade = _facade()
    result = facade.handle(
        {
            "request_id": "r-3",
            "tenant_id": "tenant-a",
            "actor_id": "actor-3",
            "action": "close",
            "payload": {"resource_id": "res-1"},
        }
    )
    assert result["ok"] is True
    assert result["data"]["resource"]["status"] == "closed"


def test_unexpected_input_missing_actor_id_rejected():
    facade = _facade()
    result = facade.handle(
        {
            "request_id": "r-4",
            "tenant_id": "tenant-a",
            "actor_id": "",
            "action": "update",
            "payload": {"resource_id": "res-1", "value": 11},
        }
    )
    assert result["ok"] is False
    assert result["reason"].startswith("invalid_payload:")
